const IMG_SRC = 'data:image/jpeg;base64,';

function loadImg(src) { const im = new Image(); im.src = src; return im; }
function framed(g, im, cx, cy, w, h, rot, zoom, a = 1) { if (!im.complete || !im.naturalWidth || a <= 0) return; g.save(); g.globalAlpha = a; g.translate(cx, cy); g.rotate(rot);
  g.fillStyle = 'rgba(0,0,0,0.25)'; g.fillRect(-w / 2 + 10, -h / 2 + 16, w + 8, h + 8); g.fillStyle = '#f7f1e3'; g.fillRect(-w / 2 - 14, -h / 2 - 14, w + 28, h + 28);
  g.save(); g.beginPath(); g.rect(-w / 2, -h / 2, w, h); g.clip(); const r = Math.max(w / im.naturalWidth, h / im.naturalHeight) * zoom, iw = im.naturalWidth * r, ih = im.naturalHeight * r; g.drawImage(im, -iw / 2, -ih / 2, iw, ih); g.restore();
  g.strokeStyle = '#1b1b1b'; g.lineWidth = 6; g.strokeRect(-w / 2 - 14, -h / 2 - 14, w + 28, h + 28); g.restore(); }
function wtext(g, t, x, y, size, col, a) { if (a <= 0) return; g.save(); g.globalAlpha = a; g.font = `800 ${size}px Baloo`; g.textAlign = 'center'; g.textBaseline = 'middle'; g.shadowColor = 'rgba(0,0,0,0.8)'; g.shadowBlur = 14; g.fillStyle = col; g.fillText(t, x, y); g.restore(); }
function seal(g, t, x, y, a) { if (a <= 0) return; g.save(); g.globalAlpha = a * 0.95; g.translate(x, y); g.rotate(0.05); g.fillStyle = '#b5281f'; g.beginPath(); g.roundRect(-78, -70, 156, 140, 12); g.fill(); g.fillStyle = '#f3e9d8'; let fs = 50; g.font = '800 50px Baloo'; while (g.measureText(t).width > 136 && fs > 24) { fs -= 2; g.font = '800 ' + fs + 'px Baloo'; } g.textAlign = 'center'; g.textBaseline = 'middle'; g.fillText(t, 0, 4); g.restore(); }
const c = makeCanvas(), g = c.getContext('2d');
const IMG = loadImg(IMG_SRC);

window.renderFrame = function (t) { const D = DURATION; NB.use('inkwash'); NB.paper(g);
  framed(g, IMG, 540, 975, 900, 760, -0.015, 1.05 + 0.12 * t / D, 1);
  const k = NB.ease(NB.cl((t - D * 0.2) / 0.8)); if (k > 0) { g.save(); g.globalAlpha = k * 0.9; g.strokeStyle = '#f3ead6'; g.lineWidth = 7; g.setLineDash([16, 14]); g.beginPath(); g.arc(610, 760, 120, Math.PI * 1.15, Math.PI * (1.15 + 0.55 * k)); g.stroke(); g.restore(); }
  wtext(g, '?', 860, 760, 170, '#ff5a4a', NB.cl((t - D * 0.65) / 0.25));
  seal(g, 'അഗസ്ത്യൻ', 160, 640, NB.cl((t - D * 0.35) / 0.3));
};
